import type { CSSProperties } from 'react'
import { isTextbookItemResolved, type TextbookUnitProgress } from '../../domain/textbook'
import type { TextbookFigure as TextbookFigureData, TextbookItem } from '../../domain/textbookSchema'

function resolveAssetSrc(src: string) {
  if (/^(?:https?:|data:|blob:)/i.test(src)) return src
  // Vite statically replaces the *direct* import.meta.env.BASE_URL expression in production.
  // Optional chaining on import.meta.env prevented reliable GitHub Pages asset prefixes.
  const viteBase = import.meta.env.BASE_URL
  const base = viteBase.endsWith('/') ? viteBase : `${viteBase}/`
  if (src.startsWith(base)) return src
  return `${base}${src.replace(/^\.?\/+/, '')}`
}

type TextbookFigureProps = {
  figure: TextbookFigureData
  items: TextbookItem[]
  progress: TextbookUnitProgress | undefined
  onOpen: (itemId: string) => void
}

export function TextbookFigure({ figure, items, progress, onOpen }: TextbookFigureProps) {
  // The 11 approved SVG sources have viewBox only, with 640x360 Venn and
  // 720x220 number-line layouts. Explicit <img> dimensions prevent zero-size
  // intrinsic layout on Chromium while the CSS still scales to narrow screens.
  const mathSetSvg = figure.src.startsWith('/assets/math/textbook/sets/') && figure.src.endsWith('.svg')
  const numberLineSvg = mathSetSvg && figure.src.includes('/number-line-')
  return (
    <figure className="reading-figure" data-testid={`textbook-figure-${figure.id}`}>
      <div className={`textbook-figure-stage${mathSetSvg ? ' textbook-figure-stage--math-set-svg' : ''}`}>
        <img src={resolveAssetSrc(figure.src)} alt={figure.alt} width={mathSetSvg ? (numberLineSvg ? 720 : 640) : undefined} height={mathSetSvg ? (numberLineSvg ? 220 : 360) : undefined} />
        {figure.overlays.map((overlay) => {
          const item = items.find((candidate) => candidate.id === overlay.itemId)
          const record = progress?.answers[overlay.itemId]
          const revealed = overlay.reveal === 'always' || Boolean(item && isTextbookItemResolved(item, record))
          if (revealed) return null

          const style = {
            left: `${overlay.x}%`,
            top: `${overlay.y}%`,
            width: `${overlay.width}%`,
            height: `${overlay.height}%`,
          } satisfies CSSProperties

          if (overlay.interactive === false) {
            return (
              <span
                key={overlay.id}
                className={`textbook-figure-overlay textbook-figure-overlay--${overlay.mode}`}
                style={style}
                data-testid={`textbook-figure-overlay-${overlay.id}`}
                aria-hidden="true"
              >
                <span aria-hidden="true">?</span>
              </span>
            )
          }

          return (
            <button
              type="button"
              key={overlay.id}
              className={`textbook-figure-overlay textbook-figure-overlay--${overlay.mode}`}
              style={style}
              data-testid={`textbook-figure-overlay-${overlay.id}`}
              aria-label={overlay.ariaLabel ?? item?.prompt ?? item?.label ?? overlay.itemId}
              onClick={() => onOpen(overlay.itemId)}
            >
              <span aria-hidden="true">?</span>
            </button>
          )
        })}
      </div>
      {figure.caption && <figcaption>{figure.caption}</figcaption>}
    </figure>
  )
}

import { InlineMath } from 'react-katex'
import { auditedResolvedWrapBlocks, auditedWrapBlocks, formulaWrapChunks } from './formulaWrap'
import type { TextbookUnitProgress } from '../../domain/textbook'
import { isTextbookItemResolved } from '../../domain/textbook'
import { normalizeTextbookMath } from '../../domain/textbookMath'
import { textbookDisplayLines } from '../../domain/textbookDisplayLines'
import type { TextbookReadingBlock, TextbookSection } from '../../domain/textbookSchema'

type FormulaBlock = Extract<TextbookReadingBlock, { type: 'formula' }>

type Props = {
  unitId: string
  block: FormulaBlock
  section: TextbookSection
  progress: TextbookUnitProgress | undefined
  onOpen: (itemId: string) => void
}

// Display-only: one solved coefficient of 1 immediately before the simple factor x+….
// Keep the recorded answer as "1" and leave constants and other algebraic forms untouched.
function isSolvedUnitCoefficientBeforeX(
  block: FormulaBlock,
  index: number,
  section: TextbookSection,
  progress: TextbookUnitProgress | undefined,
): boolean {
  const part = block.parts[index]
  const next = block.parts[index + 1]
  if (part?.type !== 'choice' || next?.type !== 'math' || !/^x\+/.test(next.latex)) return false

  const item = section.items.find((candidate) => candidate.id === part.itemId)
  if (!item || item.answerType !== 'formula') return false

  const record = progress?.answers[item.id]
  return isTextbookItemResolved(item, record) && (record?.value ?? item.answer) === '1'
}

export function TextbookFormula({ block, section, progress, onOpen, unitId }: Props) {
  const n12Formula = unitId === 'math-numbers-expressions-n12'
  const renderedParts = block.parts.map((part, index) => {
    const key = `${block.id}-part-${index}`

    if (part.type === 'math') {
      const followsUnitCoefficient = isSolvedUnitCoefficientBeforeX(block, index - 1, section, progress)
      const latex = followsUnitCoefficient ? part.latex.slice(1) : part.latex
      const arrow = '\\quad\\Longrightarrow\\quad'
      const arrowAt = n12Formula ? latex.indexOf(arrow) : -1
      if (arrowAt >= 0) {
        const left = latex.slice(0, arrowAt)
        const right = latex.slice(arrowAt + arrow.length)
        return (
          <span className="reading-formula-n12-transform" key={key}>
            {left && <span className="reading-formula-math"><InlineMath math={left} /></span>}
            <span className="reading-formula-n12-arrow" aria-label="次の式へ">↓</span>
            {right && <span className="reading-formula-math"><InlineMath math={right} /></span>}
          </span>
        )
      }
      return <span className="reading-formula-math" key={key}><InlineMath math={latex} /></span>
    }

    if (part.type === 'text') {
      return <span className="reading-formula-text" key={key}>{part.text}</span>
    }

    if (part.type === 'term') {
      return <strong className="reading-term reading-formula-term" key={key}>{part.text}</strong>
    }

    const item = section.items.find((candidate) => candidate.id === part.itemId)
    if (!item) {
      return <span className="reading-formula-missing" key={key}>□</span>
    }

    const record = progress?.answers[item.id]
    const resolved = isTextbookItemResolved(item, record)

    if (resolved) {
      const value = record?.value ?? item.answer
      const showCoefficientAsX = isSolvedUnitCoefficientBeforeX(block, index, section, progress)
      return (
        <span
          className="reading-formula-answer"
          data-testid={`resolved-${item.id}`}
          aria-label={showCoefficientAsX ? '係数は1（式ではx）' : undefined}
          key={key}
        >
          {item.answerType === 'formula'
            ? (() => {
              const lines = textbookDisplayLines(item.id, value)
              return lines.length > 1
                ? <span className="reading-formula-n12-answer-lines">
                    {lines.map((line, i) =>
                      <span key={i}><InlineMath math={normalizeTextbookMath(line)} /></span>)}
                  </span>
                : <InlineMath math={showCoefficientAsX ? 'x' : normalizeTextbookMath(lines[0])} />
            })()
            : value}
        </span>
      )
    }

    const wrong = Boolean(record)
    const localToken = ['n12-p002-', 'n12-p003-', 'n09-p001-', 'n01-r3-', 'n03-r3-'].some(prefix => item.id.startsWith(prefix))
    return (
      <button
        type="button"
        className={`reading-formula-choice${wrong ? ' reading-formula-choice--wrong' : ''}${localToken ? ' reading-formula-choice--token' : ''}`}
        data-testid={`textbook-item-${item.id}`}
        aria-label={item.prompt}
        onClick={() => onOpen(item.id)}
        key={key}
      >
        {wrong ? '×' : '選択'}
      </button>
    )
  })
  const first = block.parts[0]
  const n12Choice = block.parts[1]
  const suffix = block.parts[2]
  const q06Layout = n12Formula && block.parts.length === 3 && block.id === 'formula-q06-left-coef'
    && first?.type === 'math' && first.latex.endsWith('\\quad\\Longrightarrow\\quad')
    && n12Choice?.type === 'choice' && n12Choice.itemId === 'n12-p002-q06-left-coef'
    && suffix?.type === 'math'
  const q12Layout = n12Formula && block.parts.length === 3 && block.id === 'formula-q12-signed-coef'
    && first?.type === 'math' && first.latex.includes('=')
    && n12Choice?.type === 'choice' && n12Choice.itemId === 'n12-p002-q12-signed-coef'
    && suffix?.type === 'math'
  const transformLayout = n12Formula && block.parts.length === 3
    && ((block.id === 'formula-q02-coef' && n12Choice?.type === 'choice' && n12Choice.itemId === 'n12-p002-q02-coef')
      || (block.id === 'formula-q06-right-coef' && n12Choice?.type === 'choice' && n12Choice.itemId === 'n12-p002-q06-right-coef'))
    && first?.type === 'math' && first.latex.endsWith('\\quad\\Longrightarrow\\quad') && suffix?.type === 'math'
  const puddingLayout = n12Formula && block.id === 'formula-cost-pudding' && block.parts.length === 3
    && first?.type === 'math' && first.latex === '130\\times(20-x)='
    && n12Choice?.type === 'choice' && n12Choice.itemId === 'n12-p003-q10-pudding-coef'
    && suffix?.type === 'math' && suffix.latex === '(20-x)'
  const lowerLayout = n12Formula && block.id === 'formula-q13-lower' && block.parts.length === 2
    && first?.type === 'choice' && first.itemId === 'n12-p002-q13-lower'
    && n12Choice?.type === 'math' && n12Choice.latex === '\\le50x<3300-2650'
  const auditedWrap = auditedWrapBlocks[unitId]?.includes(block.id) ?? false
  const wrapBlock = auditedWrap ? {
    ...block,
    parts: block.parts.map((part, index) => {
      if (part.type !== 'choice' || !auditedResolvedWrapBlocks.includes(block.id)) return part
      const item = section.items.find(q => q.id === part.itemId)
      const record = progress?.answers[part.itemId]
      return item && isTextbookItemResolved(item, record)
        ? { type: 'math' as const, latex: `§a${index}§${normalizeTextbookMath(record?.value ?? item.answer)}§z${index}§` }
        : part
    }),
  } : block
  let wrappedAnswer: number | undefined
  const markedAnswers = new Set<number>()
  const grouped = q06Layout || q12Layout || transformLayout || puddingLayout
  return (
    <div
      className={`reading-formula-line${n12Formula ? ' reading-formula-line--n12' : ''}`}
      data-testid={`textbook-formula-${block.id}`}
      data-latex-status="ok"
    >
      <div className={`reading-formula-expression${grouped ? ' reading-formula-expression--p016' : ''}${lowerLayout ? ' reading-formula-expression--p017-chain' : ''}${auditedWrap ? ' reading-formula-expression--chapter-wrap' : ''}`}>
        {(q06Layout || transformLayout) && first?.type === 'math' ? (
          <>
            <span className="reading-formula-group" data-testid="p016-left">
              <InlineMath math={first.latex.slice(0, first.latex.indexOf('\\quad\\Longrightarrow\\quad'))} />
            </span>
            <span className="reading-formula-p016-arrow" aria-label="次の式へ">
              <span className="reading-formula-p016-wide" aria-hidden="true">⇒</span>
              <span className="reading-formula-p016-narrow" aria-hidden="true">↓</span>
            </span>
            <span className="reading-formula-group" data-testid="p016-right">
              {renderedParts.slice(1)}
            </span>
          </>
        ) : (q12Layout || puddingLayout) && first?.type === 'math' ? (
          <>
            <span className="reading-formula-group" data-testid="p016-left">
              <InlineMath math={first.latex.slice(0, first.latex.indexOf('='))} />
            </span>
            <span className="reading-formula-group" data-testid="p016-right">
              <InlineMath math={first.latex.slice(first.latex.indexOf('='))} />
              {renderedParts.slice(1)}
            </span>
          </>
        ) : lowerLayout ? (
          <>
            <span className="reading-formula-p017-bound" data-testid="p017-bound">
              {renderedParts[0]}<span className="reading-formula-math"><InlineMath math={'\\le50x'} /></span>
            </span>
            <span className="reading-formula-math reading-formula-p017-continuation" data-testid="p017-continuation"><InlineMath math="<3300-2650" /></span>
          </>
        ) : auditedWrap ? formulaWrapChunks(wrapBlock).map((chunk, groupIndex) => (
          <span className="reading-formula-wrap-group" key={`${block.id}-wrap-${groupIndex}`}>
            {chunk.split(/(§(?:\d+|a\d+|z\d+)§)/).filter(Boolean).map((part, partIndex) => {
              const begin = part.match(/^§a(\d+)§$/)
              if (begin) { wrappedAnswer = Number(begin[1]); return null }
              if (/^§z\d+§$/.test(part)) { wrappedAnswer = undefined; return null }
              const choice = part.match(/^§(\d+)§$/)
              const answerPart = wrappedAnswer === undefined ? undefined : block.parts[wrappedAnswer]
              const answerId = answerPart?.type === 'choice' && !markedAnswers.has(wrappedAnswer!) ? answerPart.itemId : undefined
              if (answerId) markedAnswers.add(wrappedAnswer!)
              return choice ? renderedParts[Number(choice[1])]
                : <span className="reading-formula-math" data-testid={answerId ? `resolved-${answerId}` : undefined} key={`${block.id}-wrap-${groupIndex}-${partIndex}`}><InlineMath math={part} /></span>
            })}
          </span>
        )) : renderedParts}
      </div>
    </div>
  )
}

import { useEffect, useRef, type ButtonHTMLAttributes, type KeyboardEvent, type ReactNode } from 'react'
import { AlertTriangle, CheckCircle2, Info, X } from 'lucide-react'
import { useI18n } from '../../i18n/runtime'

export function NumberedSection({ number, title, children, description }: { number: string; title: string; children: ReactNode; description?: string }) {
  return (
    <section className="numbered-section">
      <header className="section-heading"><span>{number}</span><div><h2>{title}</h2>{description && <p>{description}</p>}</div></header>
      <div className="section-body">{children}</div>
    </section>
  )
}

export function RaisedButton({ className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement>) {
  return <button type="button" className={`raised-button ${className}`} {...props} />
}

function useModalFocus(open: boolean, onEscape: () => void) {
  const ref = useRef<HTMLElement>(null)
  useEffect(() => {
    if (!open) return
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null
    const frame = window.requestAnimationFrame(() => ref.current?.querySelector<HTMLElement>('button, input, select, textarea, [href]')?.focus())
    return () => { window.cancelAnimationFrame(frame); previous?.focus() }
  }, [open])
  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === 'Escape') { event.preventDefault(); onEscape(); return }
    if (event.key !== 'Tab' || !ref.current) return
    const focusable = [...ref.current.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [href]')]
    if (!focusable.length) return
    const first = focusable[0]
    const last = focusable.at(-1)!
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
  }
  return { ref, onKeyDown }
}

export function StatusBadge({ tone = 'info', children }: { tone?: 'info' | 'success' | 'error' | 'muted'; children: ReactNode }) {
  const Icon = tone === 'success' ? CheckCircle2 : tone === 'error' ? AlertTriangle : Info
  return <span className={`status-badge status-badge--${tone}`}><Icon size={15} aria-hidden="true" />{children}</span>
}

export function ProgressBar({ value, max, label }: { value: number; max: number; label: string }) {
  const safeMax = Math.max(max, 1)
  const percent = Math.min(100, Math.max(0, (value / safeMax) * 100))
  return (
    <div className="progress-block">
      <div className="progress-label"><span>{label}</span><span>{value}/{max}</span></div>
      <div className="progress-track" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={max} aria-valuenow={value}><span style={{ width: `${percent}%` }} /></div>
    </div>
  )
}

export function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return <div className="state-panel"><span className="state-panel__mark">—</span><h2>{title}</h2><p>{body}</p>{action}</div>
}

export function ErrorState({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return <div className="state-panel state-panel--error"><AlertTriangle aria-hidden="true" /><h2>{title}</h2><p>{body}</p>{action}</div>
}

export function BottomSheet({ open, title, onClose, children }: { open: boolean; title: string; onClose: () => void; children: ReactNode }) {
  const { text } = useI18n()
  const modal = useModalFocus(open, onClose)
  if (!open) return null
  return (
    <div className="sheet-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <section ref={modal.ref} onKeyDown={modal.onKeyDown} className="bottom-sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title">
        <header><h2 id="sheet-title">{title}</h2><button type="button" className="icon-button" onClick={onClose} aria-label={text('閉じる', '关闭')}><X aria-hidden="true" /></button></header>
        <div className="bottom-sheet__body">{children}</div>
      </section>
    </div>
  )
}

export function ConfirmDialog({ open, title, body, confirmLabel, onConfirm, onCancel }: { open: boolean; title: string; body: string; confirmLabel: string; onConfirm: () => void; onCancel: () => void }) {
  const { text } = useI18n()
  const modal = useModalFocus(open, onCancel)
  if (!open) return null
  return (
    <div className="dialog-backdrop">
      <section ref={modal.ref} onKeyDown={modal.onKeyDown} className="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title" aria-describedby="confirm-body">
        <h2 id="confirm-title">{title}</h2><p id="confirm-body">{body}</p>
        <div className="button-row"><button type="button" className="text-button" onClick={onCancel}>{text('キャンセル', '取消')}</button><RaisedButton onClick={onConfirm}>{confirmLabel}</RaisedButton></div>
      </section>
    </div>
  )
}

export function stripTextbookMarkdown(value: string) {
  return value
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .trim()
}

function normalizeSubscriptSequence(value: string) {
  const map: Record<string, string> = {
    '₀':'0','₁':'1','₂':'2','₃':'3','₄':'4','₅':'5','₆':'6','₇':'7','₈':'8','₉':'9',
    'ₓ':'x','ᵧ':'y','ₜ':'t',
  }
  return [...value].map((char) => map[char] ?? char).join('')
}

function normalizeUnicodeRadicals(value: string) {
  let result = ''
  let index = 0

  while (index < value.length) {
    if (value[index] !== '√') {
      result += value[index]
      index += 1
      continue
    }

    if (value[index + 1] === '(') {
      let depth = 0
      let closingIndex = -1

      for (let cursor = index + 1; cursor < value.length; cursor += 1) {
        if (value[cursor] === '(') depth += 1
        if (value[cursor] === ')') {
          depth -= 1
          if (depth === 0) {
            closingIndex = cursor
            break
          }
        }
      }

      if (closingIndex !== -1) {
        const radicand = value.slice(index + 2, closingIndex)
        result += `\\sqrt{${normalizeUnicodeRadicals(radicand)}}`
        index = closingIndex + 1
        continue
      }
    }

    const unwrapped = value.slice(index + 1).match(/^([A-Za-z0-9Δθ⃗̄₀₁₂₃₄₅₆₇₈₉ₓᵧₜ²³_]+)/)
    if (unwrapped) {
      result += `\\sqrt{${unwrapped[1]}}`
      index += unwrapped[1].length + 1
      continue
    }

    result += '√'
    index += 1
  }

  return result
}

export function normalizeTextbookMath(value: string) {
  let next = stripTextbookMarkdown(value)

  // Plain finite-set literals like {1,4} need escaped TeX braces.
  // Never reinterpret grouping braces used by LaTeX commands (\\overline{A},
  // \\sqrt{2}, \\frac{a}{b}, etc.) or superscripts/subscripts as sets.
  next = next.replace(/\{([\-0-9A-Za-z,+\s]+)\}/g, (match, members: string, offset: number, source: string) => {
    const before = source.slice(0, offset)
    if (before.endsWith('\\') || /\\[A-Za-z]+\*?$/.test(before) || /[_^]$/.test(before)) return match
    // A two-argument TeX command has a second group after the first closing brace.
    if (/\\[A-Za-z]+\*?\{[^{}]*\}$/.test(before)) return match
    return `\\{${members}\\}`
  })
  next = normalizeUnicodeRadicals(next)

  next = next
    .replace(/overline\(([^()]*)\)/g, '\\overline{$1}')
    .replace(/\s*∩\s*/g, ' \\cap ')
    .replace(/\s*∪\s*/g, ' \\cup ')
    .replace(/\s*∈\s*/g, ' \\in ')
    .replace(/\s*∉\s*/g, ' \\notin ')
    .replace(/Δ([A-Za-z])⃗([₀₁₂₃₄₅₆₇₈₉ₓᵧₜ]+)/g, (_, base: string, sub: string) => `\\Delta \\vec{${base}}_{${normalizeSubscriptSequence(sub)}}`)
    .replace(/([A-Za-z])⃗([₀₁₂₃₄₅₆₇₈₉ₓᵧₜ]+)/g, (_, base: string, sub: string) => `\\vec{${base}}_{${normalizeSubscriptSequence(sub)}}`)
    .replace(/([A-Za-z])([₀₁₂₃₄₅₆₇₈₉ₓᵧₜ]{2,})/g, (_, base: string, sub: string) => `${base}_{${normalizeSubscriptSequence(sub)}}`)
    .replace(/([A-Za-z])_([0-9]+)_([A-Za-z])/g, '$1_{$2$3}')
    .replace(/v̄⃗/g, '\\vec{v}_{\\mathrm{avg}}')
    .replace(/([A-Za-z])̄⃗/g, '\\bar{\\vec{$1}}')
    .replace(/Δ([A-Za-z])⃗/g, '\\Delta \\vec{$1}')
    .replace(/([A-Za-z])⃗/g, '\\vec{$1}')
    .replace(/lim\(Δt→0\)/g, '\\lim_{\\Delta t\\to0}')
    .replace(/Δ/g, '\\Delta ')
    .replace(/θ/g, '\\theta ')
    .replace(/°/g, '^{\\circ}')
    .replace(/→/g, '\\to ')
    .replace(/−/g, '-')
    .replace(/×/g, '\\times ')
    .replace(/·/g, '\\cdot ')
    .replace(/}([₀₁₂₃₄₅₆₇₈₉ₓᵧₜ])/g, (_, sub: string) => `}_{${normalizeSubscriptSequence(sub)}}`)
    .replace(/₀/g, '_0')
    .replace(/₁/g, '_1')
    .replace(/₂/g, '_2')
    .replace(/₃/g, '_3')
    .replace(/₄/g, '_4')
    .replace(/₅/g, '_5')
    .replace(/₆/g, '_6')
    .replace(/₇/g, '_7')
    .replace(/₈/g, '_8')
    .replace(/₉/g, '_9')
    .replace(/ₓ/g, '_x')
    .replace(/ᵧ/g, '_y')
    .replace(/ₜ/g, '_t')
    .replace(/²/g, '^2')
    .replace(/³/g, '^3')
    .replace(/sin/g, '\\sin ')
    .replace(/cos/g, '\\cos ')
    .replace(/tan/g, '\\tan ')

  return next.trim()
}

export function looksLikeTextbookMath(value: string) {
  const text = stripTextbookMarkdown(value)
  if (!text || /[ぁ-んァ-ヶ一-龠]/.test(text)) return false
  if (/[=+\-−×÷/√²³⃗θΔ°()₀₁₂₃₄₅₆₇₈₉ₓᵧₜ_∩∪∈∉]/.test(text)) return true
  if (/overline\(/.test(text) || /^\{[^{}]+\}$/.test(text)) return true
  if (/(?:sin|cos|tan)/.test(text)) return true
  if (/^[0-9]*[A-Za-z]{1,4}$/.test(text)) return true
  return false
}

type InlineMathPart =
  | { type: 'text'; text: string }
  | { type: 'math'; latex: string }

function isMathToken(token: string) {
  const cleaned = token.replace(/^[「『（(]/, '').replace(/[」』、。！？）)]$/, '')
  if (!cleaned) return false
  if (looksLikeTextbookMath(cleaned)) return true
  return /^[POTDH][₀₁₂₃₄₅₆₇₈₉]$/.test(cleaned)
}

export function splitTextbookInlineMath(value: string): InlineMathPart[] {
  const text = stripTextbookMarkdown(value)
  if (!text) return []

  const tokenPattern = /(?:overline\([^)]*\)(?:\s*[=+\-−×·/<>|∩∪∈∉]\s*(?:overline\([^)]*\)|[A-Za-z0-9Δθ√°⃗̄₀₁₂₃₄₅₆₇₈₉ₓᵧₜ²³_{}().,+\-−×·/<>|∩∪∈∉]+))*|[A-Za-z0-9Δ√θ{][A-Za-z0-9Δθ√°⃗̄₀₁₂₃₄₅₆₇₈₉ₓᵧₜ²³_{}().,]*(?:\s*[=+\-−×·/<>|∩∪∈∉]\s*[A-Za-z0-9Δθ√°⃗̄₀₁₂₃₄₅₆₇₈₉ₓᵧₜ²³_{}().,+\-−×·/<>|∩∪∈∉]+)*|[POTDH][₀₁₂₃₄₅₆₇₈₉])/g

  const parts: InlineMathPart[] = []
  let cursor = 0
  for (const match of text.matchAll(tokenPattern)) {
    const index = match.index ?? 0
    if (index > cursor) parts.push({ type: 'text', text: text.slice(cursor, index) })
    const token = match[0]
    if (isMathToken(token)) parts.push({ type: 'math', latex: normalizeTextbookMath(token) })
    else parts.push({ type: 'text', text: token })
    cursor = index + token.length
  }
  if (cursor < text.length) parts.push({ type: 'text', text: text.slice(cursor) })

  return parts.filter((part) => part.type === 'math' || part.text.length > 0)
}

import { mathFractionDisplayValue } from './mathFractionDisplay'
import { neDevelopmentDisplayLines } from './neDevelopmentDisplay'
import { n12CostDisplayLines } from './n12CostDisplay'

/**
 * Display-only row layout for approved staged math derivations.
 * Canonical answers, comparison signs and grading strings never change.
 */
export function textbookDisplayLines(itemId: string, value: string): string[] {
  const developmentLines = neDevelopmentDisplayLines(itemId, value)
  if (developmentLines) return developmentLines.map(line => mathFractionDisplayValue(itemId, line))
  // P-004-R3: one specific long original-source choice, three independent facts.
  // Visual line breaks only; grading, stored answer and other items are unchanged.
  if (itemId === 'n07-09') return value.split(',\\;')
  // P-004-R4: three operation-and-result choices wrap only on presentation.
  if (['n11-13', 'n14-14', 'n14-15'].includes(itemId)) return value.split(',\\quad')
  // W-MATH-011/P-001: five proof decisions show sign/reason on separate rows.
  if (['n11-wm011-q02-compare', 'n11-wm011-q03-positive', 'n11-03',
    'n11-wm011-q03-zero', 'n11-wm011-q04-fraction'].includes(itemId)) return value.split(',\\quad')
  // P-004-R5: one cognitive operation plus one justified result per item.
  if (['n06-15', 'n08-10', 'n13-08'].includes(itemId)) return value.split(',\\quad')
  if (itemId === 'n09-08') {
    // Cover correct and distractor options, preserving the exact comparison operators.
    const match = /^1\.41\^2=(\d+\.\d+)([<>])2([<>])(\d+\.\d+)=1\.42\^2$/.exec(value)
    if (match) {
      const [, left, leftSign, rightSign, right] = match
      return [`1.41^2=${left}`, `${left}${leftSign}2${rightSign}${right}`, `${right}=1.42^2`]
    }
  }
  return n12CostDisplayLines(itemId, mathFractionDisplayValue(itemId, value))
}

